local mainMod = "SUPER"
local files = "thunar"
local term = "kitty"
local editor = "nvim"
local scriptsDir = os.getenv("HOME") .. "/.config/hypr/scripts"
local UserScripts = os.getenv("HOME") .. "/.config/hypr/UserScripts"
-- rofi App launcher
hl.bind(mainMod .. " + Super_L", hl.dsp.exec_cmd("pkill rofi || rofi -show drun -modi drun,filebrowser"), { release = true })
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd("pkill rofi || rofi -show drun -modi drun,filebrowser,window"))

hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(term))
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(files))

-- pyprland
hl.bind(mainMod .. " + SHIFT + Return", hl.dsp.exec_cmd("pypr toggle term"))
hl.bind(mainMod .. " + Z", hl.dsp.exec_cmd("pypr zoom"))

-- User Added Keybinds
hl.bind(mainMod .. " + SHIFT + O", hl.dsp.exec_cmd(UserScripts .. "/ZshChangeTheme.sh"))
hl.bind(mainMod .. " + SHIFT + I", hl.dsp.exec_cmd(UserScripts .. "/mpd.sh"))
--bind = $mainMod, C, exec, $UserScripts/lobster.sh #history_show
hl.bind("ALT + Space", hl.dsp.exec_cmd(UserScripts .. "/movie.sh"))
